{
  "decisions": [],
  "requested": [
    {
      "request_id": "D2k-D",
      "decision": "REQUEST_INTELLIGENCE",
      "why": "The term sheet from Fieldline Training requires four Instagram posts for an ambassador agreement starting October 1, 2026. However, the athlete currently does not operate any public-facing personal social media channels, including Instagram. It is impossible to advise on whether to accept, counter, or advance this contract without knowing if she intends to launch or already secretly operates a public Instagram channel that can support these deliverables.",
      "cites": [
        {
          "ref": "work[ctl-d-fieldline-termsheet]",
          "how": "States that the offer requires 4 Instagram posts under an ambassador agreement starting on October 1, 2026."
        },
        {
          "ref": "findings[mia.audience_scale]",
          "how": "Confirms the athlete has an extremely limited public audience scale and does not currently operate public-facing personal brand channels."
        },
        {
          "ref": "materialGaps[0]",
          "how": "Lists personal public-facing social media accounts (Instagram, TikTok, X, etc.) as a material gap in what is known."
        }
      ],
      "proposition": "Lilia Bhuta has or plans to launch a public-facing Instagram account that will be active and available to host sponsored deliverables by the contract start date of October 1, 2026.",
      "why_material": "If the athlete does not intend to operate a public Instagram account, she cannot fulfill the required deliverables of the proposed agreement. This would make the current terms impossible to execute, requiring either a rejection of the deal or a counter-offer to change the delivery platform or format.",
      "source_class": "athlete"
    }
  ],
  "deferred": []
}
